const $=selector=>document.querySelector(selector);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={studio:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',brand:'M12 3l9 5v8l-9 5-9-5V8z M3 8l9 5 9-5 M12 13v8',plan:'M5 4h14v17H5z M8 2v4 M16 2v4 M8 10h8 M8 14h8 M8 18h5',library:'M3 5h18v15H3z M3 16l5-5 5 5 3-3 5 5 M16 9h.01',calendar:'M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18 M7 14h2 M14 14h2',connect:'M9 7V3 M15 7V3 M6 7h12v3a6 6 0 0 1-12 0z M12 16v5',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M18 6L6 18',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',back:'M19 12H5 M11 6l-6 6 6 6'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.studio}"/></svg>`;
const labels={draft:'Draft',ready_for_review:'Ready for review',approved:'Approved',scheduled_local:'Queued locally',publishing:'Publication in progress',published:'Published · verified',failed:'Needs attention',verification_required:'Result needs a check',manual_due:'Native action due',simulated_published:'Demo complete',published_reported:'Published · reported',cancelled:'Cancelled',rejected:'Needs revision'};
const S={data:null,csrf:'',brandId:localStorage.getItem('virax-brand'),page:'studio',stage:0,slide:0,draft:null,dirty:false};
const brand=()=>S.data?.brands.find(b=>b.id===S.brandId);
const posts=()=>S.data?.posts.filter(p=>p.brandId===S.brandId)||[];
const references=()=>S.data?.references?.filter(r=>r.brandId===S.brandId)||[];
function referencePrompt(r){return `Continue VIRAX for ${brand().name}. Read the current private brand profile and saved rules. Reference ID: ${r.id}. Reference link: ${r.url}. My request: ${r.notes||'Adapt the idea and style for my brand.'} Inspect the actual images or video. Preserve the observed format and text treatment. Create finished original media, verify facts, and return it here for review. Resume any existing draft for this reference. Do not publish without my saved permission.`;}
function referencesView(){
  const status={needs_inspection:'Ready for your agent',inspected:'Reference inspected',draft_started:'Draft in progress',ready_for_review:'Draft checked'};
  return `${head('Your next post can start either way.','Ask for original ideas or supply a reference. Both paths use your brand rules.')}<div class="reference-layout"><section class="formpanel"><h2>I have a reference</h2><form id="referenceForm"><div class="field"><label for="referenceUrl">Paste the reference link</label><input id="referenceUrl" name="url" type="url" required placeholder="https://www.instagram.com/p/..."></div><div class="field"><label for="referenceNotes">What would you like to keep or change?</label><textarea id="referenceNotes" name="notes" placeholder="Keep the image-only carousel. Use our brand colors and show complete products."></textarea></div><button class="primary" type="submit">Save reference</button><p class="help">Your project agent creates the media. This companion saves the link and its progress.</p></form></section><section class="formpanel"><h2>I do not have references</h2><p>Give me ideas for my business. Explore seven visual directions, or use my approved style.</p><button data-action="ideasPrompt" class="primary">Give me ideas</button><p class="help">Copy a request for your project chat. Your agent creates one finished sample before a full batch.</p><button data-action="nav" data-page="plan">Explore topic ideas</button></section></div><div class="sectionhead"><div><h2>Saved references</h2><p>Continue each request in the same project chat.</p></div></div>${references().length?references().map(r=>`<article class="reference-row"><div><span class="badge">${escape(status[r.status]||r.status)}</span><p><a href="${escape(r.url)}" target="_blank" rel="noreferrer">${escape(r.url)}</a></p><p>${escape(r.notes||'Adapt the idea and style for this brand.')}</p>${r.inspection?`<small>${escape(r.inspection.format)} · ${escape(r.inspection.mode)} · ${r.inspection.slideCount} ${r.inspection.format==='carousel'?'slides':'item'}</small>`:''}</div><div class="row"><button data-action="referencePrompt" data-id="${r.id}">Copy request for chat</button>${r.postId?`<button class="primary" data-action="openPost" data-id="${r.postId}">Review draft</button>`:''}</div></article>`).join(''):'<p class="help">No reference links yet.</p>'}`;
}
function rulesPanel(){return `<section class="formpanel rule-panel"><h2>Rules that stay with your brand</h2><p>Your agent saves lasting requests here. A one-post change stays in that post.</p>${(brand().rules||[]).map(r=>`<div class="saved-rule"><p>${escape(r.text)}</p><button class="small" data-action="removeRule" data-key="${escape(r.key)}">Remove rule</button></div>`).join('')}<form id="ruleForm"><div class="field"><label for="ruleText">Save a lasting instruction</label><textarea id="ruleText" name="text" required placeholder="Always use our brand colors. Show complete products without hands."></textarea></div><button type="submit">Save brand rule</button></form></section>`;}
const assets=()=>S.data?.assets.filter(a=>a.brandId===S.brandId)||[];
const badge=status=>`<span class="badge ${['failed','verification_required'].includes(status)?'error':['draft','manual_due','rejected'].includes(status)?'warning':''}">${escape(labels[status]||status)}</span>`;
const pageTitles={studio:'Review',brand:'Brand brief',plan:'Content plan',references:'Ideas and references',library:'Asset library',calendar:'Calendar',settings:'Settings',connect:'Connections',post:'Post editor',style:'Visual direction'};
const notify=(message,error=false)=>{const node=$('#toast');node.textContent=message;node.className=`visible${error?' error':''}`;clearTimeout(S.toast);S.toast=setTimeout(()=>node.className='',6500);};
async function api(path,method='GET',body) {const response=await fetch(`/api${path}`,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':S.csrf},body:body===undefined?undefined:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw new Error(result.error||'The request failed.');return result;}
async function refresh(){S.data=await api('/state');if(!brand() && S.data.brands.length)S.brandId=S.data.brands[0].id;if(S.brandId)localStorage.setItem('virax-brand',S.brandId);}
function head(title,description,action=''){return `<div class="pagehead"><div><p class="eyebrow">${escape(brand()?.name||'VIRAX MEDIA ENGINE')}</p><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function go(page){if(S.dirty && !confirm('Leave without saving these edits?'))return;S.page=page;if(page==='brand')S.stage=brand()?.stage||0;S.draft=null;S.dirty=false;render();window.scrollTo(0,0);}
function render(){
  const b=brand();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="wordmark"><img class="virax-lockup" src="/brand/virax-technologies-lockup.svg" alt="VIRAX Technologies"></div><div class="brandline">Media Engine</div><div class="workspace"><label for="brandSwitch">Workspace</label><select id="brandSwitch" aria-label="Active brand">${S.data.brands.length?S.data.brands.map(x=>`<option value="${x.id}" ${b?.id===x.id?'selected':''}>${escape(x.name)}</option>`).join(''):'<option>Your new studio</option>'}</select></div><button class="small ghost brand-add" data-action="newBrand">＋ Add a brand</button><nav class="nav" aria-label="Main navigation">${['studio','references','library','calendar','settings'].map(p=>`<button data-action="nav" data-page="${p}" class="${S.page===p?'active':''}" ${S.page===p?'aria-current="page"':''}>${icon(p)}${pageTitles[p]}</button>`).join('')}</nav><div class="sidebar-bottom"><a href="https://github.com/vahe-s/virax-media-engine" target="_blank" rel="noreferrer">Open-source. Built to be yours. ↗</a><div class="version"><span class="dot"></span> v0.1 · Optional companion</div></div></aside><section class="content"><header class="topbar"><div class="breadcrumb">Workspace <span aria-hidden="true"> / </span><strong>${pageTitles[S.page]||'Studio'}</strong></div><div class="actions"><span class="runtime"><span class="dot"></span>${S.data.liveEnabled?'Live adapter enabled':'Review before publication'}</span>${b?`<button class="primary small" data-action="nav" data-page="references">${icon('plus')}Start a post</button>`:''}</div></header><main class="main" id="main">${pageContent()}</main></section></div>`;
}
function pageContent(){if(!brand() && !['studio','connect'].includes(S.page))return welcome();return ({studio:studio,brand:onboarding,style:directions,plan:planView,library:libraryView,calendar:calendarView,settings:settingsView,references:referencesView,connect:connections,post:postView}[S.page]||studio)();}
function welcome(){return `<div class="hero"><div><p class="eyebrow">YOUR CHAT IS THE ENGINE</p><h1>Just tell it<br>what you need.</h1><p>Set up VIRAX in a project chat. Your agent asks the questions, saves your rules, and creates the work.</p><div class="actions"><button class="primary" data-action="agentPrompt">Copy chat setup request ${icon('arrow')}</button><button class="ghost" data-action="demo">Explore the demo</button></div><small>This companion opens when you need a preview, approval, assets, or settings.</small></div><div class="hero-art"><img src="/examples/fieldwork/photos/01-ritual.jpg" alt="Ivory coffee cup on a terracotta plinth in morning light"><img src="/examples/fieldwork/photos/02-beans.jpg" alt="A close view of coffee beans in a steel scoop"><span class="hero-label">FIELDWORK · FICTIONAL BRAND EXAMPLE</span></div></div><div class="sectionhead"><div><h2>Your words become the brief.</h2><p>Ask for ideas or paste a reference. Change a preference. Ask for the next batch.</p></div><button class="small" data-action="newBrand">Set up a brand here</button></div><div class="steps"><div class="step"><span>01 / TALK</span><h3>Tell it about your business.</h3><p>Your agent asks a few useful questions at a time. No long form is required.</p></div><div class="step"><span>02 / CREATE</span><h3>Bring an idea or a reference.</h3><p>Ask for ideas without a reference, or supply one. Your agent checks facts and creates original media.</p></div><div class="step"><span>03 / REVIEW</span><h3>See the result. Make it yours.</h3><p>Review in chat or use this companion. Lasting corrections stay in your brand profile.</p></div></div>`;}
function card(p){const first=p.slides[0],src=p.render?`/api/files/${p.id}/${p.render.files[0].name}`:first.assetId?`/api/assets/${first.assetId}`:null;return `<button class="post-card" data-action="openPost" data-id="${p.id}"><div class="art">${src?`<img src="${src}" alt="${escape(first.alt||p.title)}" loading="lazy">`:`<div class="placeholder">${icon('library')}Your next idea</div>`}${badge(p.status)}</div><div class="meta"><span>${escape(p.platform)} · ${p.placement==='story'?'Story':escape(p.format)}</span><span>${p.slides.length} ${p.slides.length===1?'image':'images'} · v${p.version}</span></div><h3>${escape(p.title)}</h3></button>`;}
function studio(){if(!brand())return welcome();const list=posts();return `${head('Your work, ready for a closer look.','Your agent works in chat. Use this companion to inspect, approve, or refine the result.',`<button class="ghost" data-action="nav" data-page="brand">Brand brief ${icon('arrow')}</button>`)}${!brand().styleApproved?`<div class="notice">Set your visual direction before approval. <button class="inline-link" data-action="nav" data-page="style">Choose a style</button></div>`:''}<div class="summaryline"><span><strong>${list.filter(p=>['draft','rejected'].includes(p.status)).length}</strong>in progress</span><span><strong>${list.filter(p=>['ready_for_review','approved'].includes(p.status)).length}</strong>for review</span><span><strong>${list.filter(p=>p.status==='scheduled_local').length}</strong>in the queue</span></div>${list.length?`<div class="grid">${list.map(card).join('')}</div>`:`<div class="empty"><h2>Make the first post count.</h2><p>Start from a suggested topic or bring your own reference.</p><button class="primary" data-action="nav" data-page="plan">Explore your content plan ${icon('arrow')}</button></div>`}<div class="sectionhead"><div><h2>Keep your agent on the same page.</h2><p>Download your current rules for ChatGPT, Dot, or another agent.</p></div><a class="button small" href="/api/brands/${brand().id}/portable">${icon('download')}Brand instructions</a></div>`;}
function field(f,value){const id=`answer-${f.key}`,label=`<label for="${id}">${escape(f.label)}${f.required?' <span class="required">*</span>':''}</label>`;if(f.type==='multi')return `<fieldset class="field"><legend>${escape(f.label)}${f.required?' *':''}</legend><div class="choices">${f.options.map(o=>`<label class="checkchoice"><input type="checkbox" name="${f.key}" value="${escape(o)}" ${(value||[]).includes(o)?'checked':''}>${escape(o)}</label>`).join('')}</div><label for="custom-${f.key}">Custom prompt for this choice</label><textarea id="custom-${f.key}" name="${f.key}Custom" placeholder="Use this when you choose Custom.">${escape(brand()?.answers[f.key+'Custom']||'')}</textarea></fieldset>`;const common=`id="${id}" name="${f.key}" ${f.required?'required':''}`;const custom=['select','multi'].includes(f.type)&&f.options?.includes('Custom')&&f.key!=='cta'?`<div class="field custom-choice"><label for="custom-${f.key}">Custom prompt for this choice</label><textarea id="custom-${f.key}" name="${f.key}Custom" placeholder="Use this when you choose Custom.">${escape(brand()?.answers[f.key+'Custom']||'')}</textarea></div>`:'';const input=f.type==='textarea'?`<textarea ${common} placeholder="${escape(f.placeholder||'')}">${escape(value||'')}</textarea>`:f.type==='select'?`<select ${common}><option value="">Choose an option</option>${f.options.map(o=>`<option ${value===o?'selected':''}>${escape(o)}</option>`).join('')}</select>`:`<input ${common} value="${escape(value||'')}" placeholder="${escape(f.placeholder||'')}">`;return `<div class="field">${label}${input}${custom}</div>`;}
function onboarding(){const b=brand(),stage=S.data.stages[S.stage];return `${head('A brand brief that stays with you.',`${S.data.stages.length} short stages. Your saved answers become the instructions for every content task.`)}<div class="formlayout"><div class="stage-nav">${S.data.stages.map((s,i)=>`<button class="${i===S.stage?'active':''}" data-action="stage" data-index="${i}"><span class="stage-num">${i+1}</span><span>${escape(s.title)}</span></button>`).join('')}</div><form id="brandForm" class="formpanel"><p class="eyebrow">STEP ${S.stage+1} OF ${S.data.stages.length}</p><h2>${escape(stage.title)}</h2><p>${escape(stage.note)}</p>${stage.fields.map(f=>field(f,b.answers[f.key])).join('')}<div class="formfoot"><small>Saved profile · version ${b.version}</small><button class="primary" type="submit">${S.stage===S.data.stages.length-1?'Save and choose a style':'Save and continue'} ${icon('arrow')}</button></div></form></div>`;}
function directions(){return `${head('Choose the feeling. Keep the rules.','Explore seven direction briefs. Ask your agent for seven actual previews tailored to your business, then approve one finished sample.')}<div class="grid">${S.data.styles.map(s=>`<div class="style-card ${brand().style===s.id?'selected':''}">${s.image?`<img src="/examples/fieldwork/photos/${s.image}" alt="${escape(s.name)}: fictional coffee example">`:`<div class="style-brief-art" style="background:${s.palette[0]};color:${s.palette[2]}"><span>Direction brief</span><strong>${escape(s.name)}</strong><small>Ask your agent for a brand preview.</small></div>`}<div class="copy"><h3>${escape(s.name)}</h3><p>${escape(s.description)}</p><div class="swatches">${s.palette.map(c=>`<span class="swatch" style="background:${c}" aria-label="${c}"></span>`).join('')}</div><button class="${brand().style===s.id?'accent':'ghost'} small" data-action="chooseStyle" data-style="${s.id}">${brand().style===s.id?'Selected direction':'Use this direction'} ${icon('check')}</button></div></div>`).join('')}</div><div class="notice mt">These catalog choices are not finished brand previews. Approve one real sample before a full batch. <button data-action="ideasPrompt" class="inline-link">Copy preview request</button></div><div class="notice mt">A reference can override the layout. Image-only references stay image-only. Your logo, colors, and font rules remain in the profile.</div><div class="row"><button data-action="chooseStyle" data-style="custom" class="ghost">Use my supplied references</button><button data-action="nav" data-page="library" class="primary">Add brand files ${icon('arrow')}</button></div>`;}
function planView(){const plan=S.plan;if(!plan){loadPlan();return head('Your content plan','Read your business answers to prepare relevant topic suggestions.');}return `${head('Useful ideas. A realistic rhythm.',`${plan.frequency} main posts each week. ${plan.entries.length} draft slots across two weeks.`)}<div class="notice">${escape(plan.basis)}<br>${escape(plan.timingBasis)}${(plan.notes||[]).map(note=>`<p>${escape(note)}</p>`).join('')}</div>${plan.followups.length?`<div class="notice warning"><strong>A few details need a closer look.</strong><ul>${plan.followups.map(f=>`<li>${escape(f)}</li>`).join('')}</ul><button class="small" data-action="nav" data-page="brand">Refine the brief</button></div>`:''}<div>${plan.entries.map((p,i)=>`<div class="plan-row"><span class="num">Day ${p.day}</span><div><h3>${escape(p.title)}</h3><p>Week ${p.week} · ${escape(p.type)} · ${escape(p.format)} · ${p.mode}${p.story?" + separate Story":""}</p><p>${escape(p.purpose)}</p><small>CTA: ${escape(p.cta)}<br>Needs: ${escape(p.requires)}</small></div><button class="small" data-action="useTopic" data-index="${i}">Create brief ${icon('plus')}</button></div>`).join('')}</div><p class="help mt">Topic suggestions are editorial starting points. Your agent must inspect references and verify facts before the draft is ready.</p>`;}
async function loadPlan(){if(S.planLoading)return;S.planLoading=true;try{S.plan=await api(`/brands/${S.brandId}/plan`);if(S.page==='plan')render();}catch(e){notify(e.message,true);}finally{S.planLoading=false;}}
function settingsView(){const b=brand(),creative=S.data.stages.find(s=>s.id==='creative'),content=S.data.stages.find(s=>s.id==='content'),source=S.data.stages.find(s=>s.id==='facts').fields.find(f=>f.key==='sourceDisplay'),drive=S.data.drive||{},sync=drive.brands?.find(x=>x.brandId===b.id);return `${head('Your rules. Your creative control.','Choose the mix, the main CTA, and the source policy. Save your work to Google Drive when connected.')}<div class="toolbar"><button data-action="nav" data-page="brand">Brand brief</button><button data-action="nav" data-page="plan">Content plan</button><button data-action="nav" data-page="connect">Connections</button></div>${rulesPanel()}<div class="settings-grid"><section class="formpanel"><h2>Content preferences</h2><p>Use exact weekly counts or random variety. Your custom prompt stays with every agent task.</p><form id="settingsForm">${[S.data.stages.find(s=>s.id==='media').fields.find(f=>f.key==='creativeStart'),content.fields[0],content.fields[1],content.fields[2],...creative.fields,source,S.data.stages.find(s=>s.id==='delivery').fields.find(f=>f.key==='tips')].map(f=>field(f,b.answers[f.key])).join('')}<div class="notice">Every post requires a fact check. Uncertain claims cannot be presented as facts. Random choices still follow your brand and reference.</div><button class="primary" type="submit">Save content settings</button><button type="button" class="ghost" data-action="randomizePlan">Create a new random mix</button><p class="help">Saved changes create a new brand version. Affected posts need a new review.</p></form></section><section class="formpanel drive-panel"><h2>Google Drive sync</h2><p>Keep profiles, original assets, post versions, captions, sources, and publication records in a private folder.</p><span class="badge">${drive.connected?'Connected':drive.configured?'Ready to connect':'Google app setup required'}</span>${drive.account?`<p>${escape(drive.account)}</p>`:''}<p class="help">${sync?`Status: ${escape(sync.state)}. ${sync.lastSyncedAt?'Last complete sync: '+escape(new Date(sync.lastSyncedAt).toLocaleString()):'No complete sync yet.'}`:'This brand has no active sync.'}</p>${sync?.error?`<div class="notice warning">${escape(sync.error)}</div>`:''}<div class="row"><button data-action="driveConnect" ${drive.configured?'':'disabled'}>${drive.connected?'Reconnect Google':'Connect Google Drive'}</button><a class="button small" href="/docs/google-drive.md" target="_blank">Setup guide ↗</a></div>${drive.connected?`<form id="driveForm" class="mt"><label class="checkrow"><input type="checkbox" name="enabled" ${sync?.enabled?'checked':''}>Sync this brand's files to my connected Google Drive account.</label><label class="checkrow"><input type="checkbox" name="automatic" ${sync?.automatic?'checked':''}>Automatically sync after changes while the engine is online.</label><button class="primary" type="submit">Save sync settings</button><button type="button" data-action="driveSync" ${sync?.enabled&&!drive.busy?'':'disabled'}>Sync now / retry</button></form><button class="small danger mt" data-action="driveDisconnect">Disconnect Google Drive</button>`:''}${sync?.folderUrl?`<p><a href="${escape(sync.folderUrl)}" target="_blank" rel="noreferrer">Open the verified Drive folder ↗</a></p>`:''}<p class="help">This is a backup sync from the engine to Drive. Online edits create a conflict; they never silently overwrite your local rules.</p><p class="help">Tokens and passwords stay outside the backup. Drive does not run the publication queue.</p></section></div>`;}
function libraryView(){const list=assets();return `${head('The details that make it yours.','Keep logos, photographs, font files, and brand guides with the correct brand.',`<button class="primary" data-action="upload">${icon('plus')}Add files</button>`)}${list.length?`<div class="asset-grid">${list.map(a=>`<div class="asset-card">${['image','logo'].includes(a.role)?`<img src="/api/assets/${a.id}" alt="${escape(a.name)}" loading="lazy">`:`<div class="placeholder">${icon('library')}${escape(a.role)}</div>`}<div class="copy"><strong>${escape(a.name)}</strong><small>${a.width?`${a.width} × ${a.height}`:escape(a.role)} · ${a.rightsConfirmed?'Rights confirmed':'Rights need a check'}</small></div></div>`).join('')}</div>`:`<div class="empty"><h2>Your brand starts here.</h2><p>Add a logo, a few photographs, or the brand kit you already use.</p><button class="primary" data-action="upload">Add your first file</button></div>`}<p class="help mt">Assets stay in your private data folder. Upload the exported instructions to Google Drive through your connected agent.</p>`;}
function calendarView(){const tz=brand().answers.timezone||'UTC',today=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),date=new Date(`${today}T12:00:00Z`);const days=Array.from({length:14},(_,i)=>{const d=new Date(date);d.setUTCDate(date.getUTCDate()+i);return {key:d.toISOString().slice(0,10),label:d.toLocaleDateString('en-US',{timeZone:'UTC',weekday:'short'}),day:d.getUTCDate()};});const list=posts().filter(p=>p.schedule);return `${head('Two weeks, clearly planned.',`All times use ${escape(tz)}. Local queue entries need this service online at the due time.`)}<div class="notice">Queued locally means the engine holds the schedule. It does not mean Meta holds a native schedule.</div><div class="calendar-grid">${days.map((d,i)=>`<div class="calendar-day ${i===0?'today':''}"><div class="day-label"><span>${d.label}</span><strong>${d.day}</strong></div>${list.filter(p=>p.schedule.local.startsWith(d.key)).map(p=>`<button class="calendar-event" data-action="openPost" data-id="${p.id}">${escape(p.title)}<span>${p.schedule.local.slice(11)} · ${p.placement==='story'?'Story':'Feed'}</span><span>${escape(labels[p.status])}</span></button>`).join('')}</div>`).join('')}</div><div class="sectionhead"><div><h2>Queue and publication records</h2><p>Each Feed post and Story has its own state.</p></div><button class="small" data-action="tick">Check due items</button></div>${list.length?list.map(p=>`<div class="plan-row"><span>${icon('calendar')}</span><div><h3>${escape(p.title)}</h3><p>${escape(p.schedule.local.replace('T',' '))} · ${escape(p.schedule.timezone)} · ${escape(p.schedule.account)} · ${escape(labels[p.status])}</p>${p.error?`<small>${escape(p.error)}</small>`:''}</div><button class="small" data-action="openPost" data-id="${p.id}">Open</button></div>`).join(''):'<p class="help">Approve a post, then choose its account and schedule.</p>'}`;}
function connections(){return `${head('Connect what you need.','Start with your existing tools. The demo never sends content to a social account.')}<div class="notice">${S.data.liveEnabled?'The live adapter is enabled. Every post still needs valid content approval and publication permission.':'Live publication is off. You can complete setup, media creation, review, exports, and queue tests.'}</div>${S.data.capabilities.map(c=>`<div class="connection"><h3>${escape(c.name)}</h3><p>${escape(c.detail)}</p><span class="badge">${escape(c.state.replaceAll('_',' '))}</span></div>`).join('')}<div class="row mt"><button class="primary" data-action="verifyMeta">Verify Meta account</button><a class="button" href="/docs/platforms.md" target="_blank">Connection guide ↗</a><button data-action="agentPrompt">Copy agent setup prompt</button><button data-action="demo">Open example studio</button></div>${S.data.connection?`<p class="help">Account identity checked: ${escape(S.data.connection.instagram?.account||S.data.connection.facebook?.account)}. This check alone does not prove live publication.</p>`:''}<div class="sectionhead"><div><h2>Saved publication permissions</h2><p>Revoke a grant to stop future use of its scope.</p></div></div>${S.data.grants.filter(g=>g.brandId===S.brandId).map(g=>`<div class="connection"><h3>${escape(g.account)}</h3><p>${g.scope} · ${g.platform} ${g.placement} · ${g.provider} · expires ${escape(g.expiresAt.slice(0,10))}</p>${g.revoked?'<span class="badge">Revoked</span>':`<button class="small danger" data-action="revoke" data-id="${g.id}">Revoke</button>`}</div>`).join('')||'<p class="help">No publication permission is active for this brand.</p>'}<div class="sectionhead"><div><h2>Recent activity</h2><p>A durable record of changes and results.</p></div></div><div class="log">${S.data.events.slice(0,15).map(e=>`<div class="logrow"><time>${escape(new Date(e.at).toLocaleString())}</time><div><strong>${escape(e.action.replaceAll('_',' '))}</strong>${e.detail?`<p>${escape(e.detail)}</p>`:''}</div></div>`).join('')}</div>`;}
function claimFields(c,i){return `<div class="claim-row"><div class="field"><label>Statement for slide ${c.slide}</label><textarea data-claim="${i}" data-key="claim">${escape(c.claim)}</textarea></div><div class="split"><div class="field"><label>Type</label><select data-claim="${i}" data-key="kind">${['unverified','verified_fact','business_fact','editorial_advice','illustration'].map(t=>`<option value="${t}" ${c.kind===t?'selected':''}>${t.replaceAll('_',' ')}</option>`).join('')}</select></div><div class="field"><label>Checked on</label><input type="date" data-claim="${i}" data-key="checkedOn" value="${escape(c.checkedOn)}"></div></div><div class="field"><label>Primary source URL</label><input data-claim="${i}" data-key="source" value="${escape(c.source)}" placeholder="https://"></div><div class="field"><label>Limits and qualifications</label><textarea data-claim="${i}" data-key="caveat">${escape(c.caveat)}</textarea></div><div class="field"><label>Who checked this claim?</label><input data-claim="${i}" data-key="reviewer" value="${escape(c.reviewer)}"></div></div>`;}
function postView(){const p=S.draft;if(!p)return '';const slide=p.slides[S.slide],b=brand(),src=p.render&&!S.dirty?`/api/files/${p.id}/${p.render.files[S.slide]?.name?.replace('.jpg','-phone.jpg')}`:slide.assetId?`/api/assets/${slide.assetId}`:null;const isLocked=['published','publishing','published_reported','simulated_published','verification_required','manual_due','scheduled_local'].includes(p.status);return `${head(escape(p.title),`${escape(p.platform)} ${p.placement==='story'?'Story':'Feed'} · Version ${p.version} · ${escape(labels[p.status])}`,`<button class="ghost small" data-action="nav" data-page="studio">${icon('back')}All posts</button>`)}<div class="toolbar"><button data-action="taskPack">${icon('download')}Agent brief</button><button data-action="renderPost" ${isLocked?'disabled':''}>Export media</button>${p.render?`<a class="button" href="/api/posts/${p.id}/download">${icon('download')}Download pack</a>`:''}<button data-action="story">Create Story</button><button data-action="duplicate">New revision</button>${['approved','scheduled_local'].includes(p.status)?'<button class="primary" data-action="schedule">Choose publication time</button>':''}${p.status==='manual_due'?'<button class="primary" data-action="manualReceipt">Record native result</button>':''}${p.status==='failed'?'<button data-action="retry">Retry safe failure</button>':''}${['approved','scheduled_local','manual_due'].includes(p.status)?'<button class="danger" data-action="cancelPost">Cancel</button>':''}</div>${p.error?`<div class="notice warning">${escape(p.error)}</div>`:''}${p.receipt?`<div class="notice">${p.receipt.simulated?'Demo result only. Nothing was sent to a platform.':p.receipt.verified?'The platform result was read back and verified.':'This result was reported. It has no independent API check.'}${p.receipt.url?` <a href="${escape(p.receipt.url)}" target="_blank" rel="noreferrer">Open post ↗</a>`:''}</div>`:''}<div class="post-layout"><div class="preview">${src?`<img class="phone-image" src="${src}" alt="${escape(slide.alt||'Selected slide')}">`:`<div class="preview-placeholder placeholder">${icon('library')}Add artwork for this slide</div>`}<p class="preview-caption">${p.render&&!S.dirty?'Final export · displayed at up to 390 px':'Source image · export required for final review'} · ${S.slide+1} / ${p.slides.length}</p><div class="thumbs">${p.slides.map((s,i)=>`<button aria-label="Slide ${i+1}" class="thumb ${i===S.slide?'active':''}" data-action="slide" data-index="${i}">${s.assetId?`<img src="/api/assets/${s.assetId}" alt="">`:i+1}</button>`).join('')}</div>${S.quality?`<div class="notice ${S.quality.passed?'':'warning'}"><strong>${S.quality.passed?'Quality checks complete':'Before this post is ready'}</strong>${S.quality.errors.length?`<ul class="issues">${S.quality.errors.map(e=>`<li>${escape(e)}</li>`).join('')}</ul>`:''}${S.quality.warnings.length?`<ul class="issues">${S.quality.warnings.map(e=>`<li>${escape(e)}</li>`).join('')}</ul>`:''}</div>`:''}</div><div class="editor"><form id="postForm"><fieldset ${isLocked?'disabled':''} style="border:0;padding:0;margin:0"><h2>Make this slide count.</h2><div class="field"><label for="postTitle">Post title</label><input id="postTitle" name="title" value="${escape(p.title)}"></div><div class="split"><div class="field"><label for="postMode">Image treatment</label><select id="postMode" name="mode"><option value="image-only" ${p.mode==='image-only'?'selected':''}>Images only</option><option value="educational" ${p.mode==='educational'?'selected':''}>Images with text</option></select></div>${p.music!=='none'?`<div class="field"><label for="postMusic">Saved music requirement (manual only)</label><select id="postMusic" name="music">${['none','optional','required'].map(m=>`<option ${p.music===m?'selected':''}>${m}</option>`).join('')}</select></div>`:''}</div>${p.mode==='educational'?`<div class="field"><label for="artworkMode">Text layout</label><select id="artworkMode" name="artworkMode"><option value="overlay" ${p.artworkMode!=='finished'?'selected':''}>Add text during export</option><option value="finished" ${p.artworkMode==='finished'?'selected':''}>The artwork already contains its text</option></select><small>Finished artwork keeps its existing layout. Record its text below for review.</small></div>`:''}<div class="field"><label for="slideAsset">Slide ${S.slide+1} image</label><select id="slideAsset" name="assetId"><option value="">Choose an image</option>${assets().filter(a=>a.role==='image').map(a=>`<option value="${a.id}" ${slide.assetId===a.id?'selected':''}>${escape(a.name)}</option>`).join('')}</select></div>${p.mode==='educational'?`<div class="field"><label for="slideHeadline">Headline</label><input id="slideHeadline" name="headline" value="${escape(slide.headline)}"></div><div class="field"><label for="slideBody">Body text</label><textarea id="slideBody" name="body">${escape(slide.body)}</textarea><small>${p.artworkMode==='finished'?'This records the text already in the artwork. Inspect its size in the final preview.':'Keep it short. Export uses at least 52 px body text.'}</small></div>`:''}<div class="field"><label for="slideAlt">Alt text</label><textarea id="slideAlt" name="alt">${escape(slide.alt)}</textarea></div><details><summary>Visual brief for this slide</summary>${['message','evidence','composition','callouts'].map(key=>`<div class="field"><label for="brief-${key}">${{message:'What does this slide say?',evidence:'What must be visible?',composition:'How should the scene look?',callouts:'Which markers or callouts are needed?'}[key]}</label><textarea id="brief-${key}" name="${key}">${escape(slide[key])}</textarea></div>`).join('')}</details><details><summary>Claims and primary sources</summary>${p.claims.map((c,i)=>c.slide===S.slide+1?claimFields(c,i):'').join('')}<button type="button" class="small" data-action="addClaim">${icon('plus')}Add a claim or editorial note</button></details><details open><summary>Caption for the post</summary><div class="field"><textarea name="caption" aria-label="Post caption" rows="5">${escape(p.caption)}</textarea></div></details><button type="submit" class="primary">Save this version</button></fieldset></form><details open><summary>Inspect the final export</summary><p class="help">Check this slide without zoom. These checks record an inspection; they do not perform it.</p><label class="checkrow"><input id="qaVisual" type="checkbox" ${slide.qa?.visual?'checked':''}>The image clearly matches the brief and is physically plausible.</label><label class="checkrow"><input id="qaPhone" type="checkbox" ${slide.qa?.phone?'checked':''}>Text and important details are clear at phone size.</label><label class="checkrow"><input id="qaAccuracy" type="checkbox" ${p.accuracy?.checked?'checked':''}>I checked every fact in the images and caption. No unsupported fact remains.</label><label class="checkrow"><input id="qaSources" type="checkbox" ${p.accuracy?.sourcesShown?'checked':''}>Public sources follow the brand preference, or this post needs no public source.</label><button class="small" data-action="reviewSlide" ${!p.render||S.dirty||isLocked?'disabled':''}>Save checks for slide ${S.slide+1}</button><div class="row mt"><button class="primary" data-action="approve" ${S.quality?.passed&&!isLocked?'':'disabled'}>Approve this content</button><button data-action="reject" class="small danger" ${isLocked?'disabled':''}>Request revision</button></div></details></div></div>`;}
function modal(html){$('#modal').innerHTML=`<button class="close" data-action="closeModal" aria-label="Close dialog">${icon('close')}</button>${html}`;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function download(name,object){const blob=new Blob([JSON.stringify(object,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function syncPost(){if(!S.draft || !$('#postForm'))return;const f=new FormData($('#postForm')),p=S.draft,s=p.slides[S.slide];for(const key of ['title','mode','caption','music','artworkMode'])if(f.has(key))p[key]=f.get(key);for(const key of ['assetId','headline','body','alt','message','evidence','composition','callouts'])if(f.has(key))s[key]=f.get(key)||null;if(p.mode==='image-only'){s.headline='';s.body='';s.callouts='';}document.querySelectorAll('[data-claim]').forEach(el=>p.claims[Number(el.dataset.claim)][el.dataset.key]=el.value);}
async function openPost(id){S.draft=structuredClone(S.data.posts.find(p=>p.id===id)||await api(`/posts/${id}`));S.brandId=S.draft.brandId;S.slide=0;S.page='post';S.dirty=false;S.quality=await api(`/posts/${id}/quality`);render();}
async function savePost(){syncPost();S.draft=await api(`/posts/${S.draft.id}`,'PUT',S.draft);S.dirty=false;await refresh();S.quality=await api(`/posts/${S.draft.id}/quality`);render();}
function showSchedule(){const p=S.draft,b=brand(),grants=S.data.grants.filter(g=>g.brandId===p.brandId&&!g.revoked&&Date.parse(g.expiresAt)>Date.now()&&g.platform===p.platform&&g.placement===p.placement&&(g.scope==='ongoing'||g.versions[p.id]===p.version));const future=new Date(Date.now()+86400000),local=p.schedule?.local||new Intl.DateTimeFormat('sv-SE',{timeZone:b.answers.timezone||'UTC',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(future).replace(' ','T');modal(`<h2>Choose the account and time.</h2><p>This adds the approved version to the engine’s queue.</p><form id="scheduleForm"><div class="field"><label for="existingGrant">Publication permission</label><select id="existingGrant" name="grantId"><option value="">Authorize this post below</option>${grants.map(g=>`<option value="${g.id}" ${p.grant===g.id?'selected':''}>${escape(g.account)} · ${g.provider} · ${g.scope}</option>`).join('')}</select></div><div class="split"><div class="field"><label for="provider">Method</label><select id="provider" name="provider"><option value="demo">Demo (sends nothing)</option><option value="manual">Native manual step</option><option value="meta">Meta API</option></select></div><div class="field"><label for="account">Destination account</label><input id="account" name="account" value="${escape(p.schedule?.account||'')}" placeholder="Exact username or Page name"></div></div><div class="field"><label for="metaAccountId">Meta destination ID (Meta method only)</label><input id="metaAccountId" name="accountId" value="${escape(S.data.connection?.[p.platform]?.id||'')}" placeholder="Verify the connected account first"></div><div class="field"><label for="localDate">Date and time</label><input id="localDate" type="datetime-local" name="local" value="${local}" required></div><div class="split"><div class="field"><label for="timeZone">Timezone</label><input id="timeZone" name="timezone" value="${escape(b.answers.timezone||'UTC')}" required></div><div class="field"><label for="occurrence">If the clock repeats this time</label><select id="occurrence" name="occurrence"><option value="reject">Ask me first</option><option value="earlier">First occurrence</option><option value="later">Second occurrence</option></select></div></div><label class="checkrow"><input type="checkbox" name="authorize">I authorize this exact version for the stated account and method. Existing valid permission does not need renewal.</label><button class="primary" type="submit">Save permission and queue</button></form>`);}
async function action(button){const a=button.dataset.action,id=button.dataset.id;
  if(a==='ideasPrompt'){const prompt=`Continue VIRAX for ${brand().name}. Read the current private brand profile and approved examples. I do not have references. Give me ideas. Suggest useful content for my audience. For a new style, show seven distinct visual previews tailored to my business. Let me combine or change directions. Create one finished sample and get my approval before a full batch. If a suitable approved sample exists, use it. Verify factual claims and use available authorized tools. Do not publish without my saved permission.`;modal(`<h2>Your idea request</h2><p>Copy this request into your project chat.</p><pre>${escape(prompt)}</pre>`);try{await navigator.clipboard.writeText(prompt);notify('Idea request copied. Paste it into your project chat.');}catch{notify('Copy the request shown here.');}return;}
  if(a==='referencePrompt'){const reference=references().find(r=>r.id===id);await navigator.clipboard.writeText(referencePrompt(reference));notify('Request copied. Paste it into this brand’s project chat.');return;}
  if(a==='removeRule'){await api(`/brands/${S.brandId}/rule`,'POST',{version:brand().version,key:button.dataset.key,remove:true});await refresh();render();notify('Rule removed from the current brand profile.');return;}
  if(a==='randomizePlan'){await api(`/brands/${S.brandId}`,'PUT',{version:brand().version,answers:{randomSeed:String(Date.now())}});S.plan=null;await refresh();go('plan');return;}
  if(a==='driveConnect'){const result=await api('/drive/connect','POST',{});location.href=result.url;return;}
  if(a==='driveSync'){notify('Google Drive sync started. Existing files remain available.');await api('/drive/sync','POST',{brandId:S.brandId});await refresh();render();notify('Google Drive confirmed the synchronized file bytes.');return;}
  if(a==='driveDisconnect'){await api('/drive/disconnect','POST',{});await refresh();render();notify('Google Drive disconnected. Existing backup files remain.');return;}
  if(a==='nav'){S.plan=null;go(button.dataset.page);return;}
  if(a==='closeModal'){closeModal();return;}
  if(a==='newBrand'){modal('<h2>Start with your business.</h2><p>You can refine every detail during setup.</p><form id="newBrandForm"><div class="field"><label for="brandName">Business name</label><input id="brandName" name="name" required placeholder="Your business"></div><button class="primary">Create brand</button></form>');return;}
  if(a==='demo'){notify('Prepare the example studio…');const result=await api('/demo','POST',{});S.brandId=result.brandId;await refresh();S.page='studio';render();return;}
  if(a==='stage'){S.stage=Number(button.dataset.index);render();return;}
  if(a==='chooseStyle'){await api(`/brands/${S.brandId}/style`,'POST',{style:button.dataset.style});await refresh();notify('Visual direction saved.');render();return;}
  if(a==='newPost'){if(!brand())return action({dataset:{action:'newBrand'}});modal(`<h2>Make room for a new idea.</h2><form id="newPostForm"><div class="field"><label for="newTitle">Working title</label><input id="newTitle" name="title" required placeholder="A useful question or a striking visual idea"></div><div class="split"><div class="field"><label for="format">Format</label><select id="format" name="format"><option value="carousel">Carousel · nine slides</option><option value="single">Single image</option><option value="story">Instagram Story</option></select></div><div class="field"><label for="mode">Image treatment</label><select id="mode" name="mode"><option value="educational">Educational</option><option value="image-only">Images only</option></select></div></div><div class="field"><label for="platform">Platform</label><select id="platform" name="platform"><option value="instagram">Instagram</option><option value="facebook">Facebook</option></select></div><button class="primary">Create brief</button></form>`);return;}
  if(a==='useTopic'){const topic=S.plan.entries[Number(button.dataset.index)];const p=await api('/posts','POST',{brandId:S.brandId,title:topic.title,format:topic.format,mode:topic.mode,creativeIntent:{type:topic.type,cta:topic.cta,customPrompt:topic.customPrompt}});await refresh();await openPost(p.id);return;}
  if(a==='openPost'){await openPost(id);return;}
  if(a==='slide'){syncPost();S.slide=Number(button.dataset.index);render();return;}
  if(a==='upload'){modal(`<h2>Add the files behind your brand.</h2><form id="uploadForm"><div class="field"><label for="uploadFiles">Files</label><input id="uploadFiles" name="files" type="file" multiple required></div><div class="field"><label for="assetRole">File type</label><select id="assetRole" name="role"><option value="image">Content photographs</option><option value="logo">Logo (PNG, JPEG, WebP)</option><option value="brand-kit">Brand guide (PDF, SVG, text, JSON)</option><option value="font">Font (TTF, OTF)</option></select></div><div class="field"><label for="fontFamily">Exact font family, for font files</label><input id="fontFamily" name="fontFamily"></div><div class="field"><label for="provenance">Source and license</label><textarea id="provenance" name="provenance" placeholder="Where did these files come from? Which permission covers their use?"></textarea></div><label class="checkrow"><input type="checkbox" name="rightsConfirmed">I own these files or have permission to use them.</label><button class="primary">Upload to this brand</button></form>`);return;}
  if(a==='renderPost'){if(S.dirty)await savePost();S.draft=await api(`/posts/${S.draft.id}/render`,'POST',{});await refresh();S.quality=await api(`/posts/${S.draft.id}/quality`);notify('Final images exported. Inspect every slide before approval.');render();return;}
  if(a==='taskPack'){syncPost();if(S.dirty)await savePost();const pack=await api(`/posts/${S.draft.id}/task`);download('virax-agent-task.json',pack);notify('Attach this task to your agent with START-HERE.md.');return;}
  if(a==='addClaim'){syncPost();S.draft.claims.push({slide:S.slide+1,claim:'',kind:'unverified',source:'',checkedOn:'',caveat:'',reviewer:''});S.dirty=true;render();return;}
  if(a==='reviewSlide'){const checked={number:S.slide+1,visual:$('#qaVisual').checked,phone:$('#qaPhone').checked};const result=await api(`/posts/${S.draft.id}/review`,'POST',{version:S.draft.version,reviewer:'Reviewer via studio',accuracy:$('#qaAccuracy').checked,sourcesShown:$('#qaSources').checked,slides:[checked]});S.draft=result.post;S.quality=result.quality;await refresh();render();return;}
  if(a==='approve'||a==='reject'){S.draft=await api(`/posts/${S.draft.id}/decision`,'POST',{version:S.draft.version,action:a==='approve'?'approve':'reject',reviewer:'Reviewer via studio'});await refresh();notify(a==='approve'?'Content approved. Publication still needs a saved scope.':'Revision requested.');render();return;}
  if(a==='schedule'){showSchedule();return;}
  if(a==='story'||a==='duplicate'){if(S.dirty)await savePost();const p=await api(`/posts/${S.draft.id}/${a==='story'?'story':'duplicate'}`,'POST',{});await refresh();await openPost(p.id);return;}
  if(a==='cancelPost'){S.draft=await api(`/posts/${S.draft.id}/cancel`,'POST',{});await refresh();render();return;}
  if(a==='retry'){S.draft=await api(`/posts/${S.draft.id}/retry`,'POST',{});await refresh();render();return;}
  if(a==='revoke'){await api(`/grants/${id}/revoke`,'POST',{});await refresh();render();return;}
  if(a==='tick'){const result=await api('/worker/tick','POST',{});await refresh();notify(result.length?`${result.length} queue item(s) checked.`:'No items are due.');render();return;}
  if(a==='verifyMeta'){await api('/connections/meta/verify','POST',{});await refresh();notify('Account identity verified. Review the connection guide before a live test.');render();return;}
  if(a==='agentPrompt'){await navigator.clipboard.writeText('Set up VIRAX Media Engine in a separate project for my business: https://github.com/vahe-s/virax-media-engine. Read START-HERE.md. Work with me in this chat. Ask up to three questions at a time, save my lasting preferences, and use the optional companion only when useful. Offer ideas without references and supplied references as equal paths. Show seven distinct style previews. Get approval for one finished sample before a full batch. Give regular useful tips about functions available to me.');notify('Chat setup request copied. Paste it into your project chat.');return;}
  if(a==='manualReceipt'){modal(`<h2>Record the native result.</h2><p>This records your report. It does not claim an independent platform check.</p><form id="receiptForm"><div class="field"><label for="receiptUrl">Actual post link</label><input id="receiptUrl" name="url" type="url" required></div><div class="field"><label for="receiptAccount">Exact account</label><input id="receiptAccount" name="account" value="${escape(S.draft.schedule.account)}" required></div>${S.draft.music==='required'?'<label class="checkrow"><input type="checkbox" name="musicVerified">I checked that required music is attached.</label>':''}<button class="primary">Record result</button></form>`);return;}
}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();button.disabled=true;try{await action(button);}catch(error){notify(error.message,true);}finally{button.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.closest('#postForm'))S.dirty=true;});
document.addEventListener('change',async event=>{if(event.target.id==='brandSwitch'){S.brandId=event.target.value;S.plan=null;S.draft=null;S.dirty=false;S.page='studio';localStorage.setItem('virax-brand',S.brandId);render();}if(['postMode','slideAsset'].includes(event.target.id)){syncPost();S.dirty=true;render();}});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target,submit=form.querySelector('[type="submit"],button:not([type])'),f=new FormData(form);if(submit)submit.disabled=true;
  try {
    if(form.id==='referenceForm'){const reference=await api('/references','POST',{brandId:S.brandId,url:f.get('url'),notes:f.get('notes')});await refresh();render();modal(`<h2>Reference saved.</h2><p>Continue with your agent in the project chat. It will inspect the reference before it creates the media.</p><pre>${escape(referencePrompt(reference))}</pre><button class="primary" data-action="referencePrompt" data-id="${reference.id}">Copy request for chat</button>`);}
    if(form.id==='ruleForm'){await api(`/brands/${S.brandId}/rule`,'POST',{version:brand().version,key:`rule-${Date.now()}`,text:f.get('text')});await refresh();render();notify('Lasting rule saved. Future tasks will read the new profile version.');}
    if(form.id==='newBrandForm'){const b=await api('/brands','POST',{name:f.get('name')});S.plan=null;S.brandId=b.id;S.stage=0;S.page='references';closeModal();await refresh();render();}
    if(form.id==='settingsForm'){const fields=[S.data.stages.find(s=>s.id==='media').fields.find(f=>f.key==='creativeStart'),S.data.stages.find(s=>s.id==='delivery').fields.find(f=>f.key==='tips'),...S.data.stages.find(s=>s.id==='content').fields.slice(0,3),...S.data.stages.find(s=>s.id==='creative').fields,S.data.stages.find(s=>s.id==='facts').fields.find(f=>f.key==='sourceDisplay')],answers={};for(const item of fields){answers[item.key]=item.type==='multi'?f.getAll(item.key):f.get(item.key);if(f.has(item.key+'Custom'))answers[item.key+'Custom']=f.get(item.key+'Custom');}await api(`/brands/${S.brandId}`,'PUT',{version:brand().version,answers});await refresh();S.plan=null;render();notify('Content settings saved to the versioned brand profile.');}
    if(form.id==='driveForm'){await api('/drive/configure','POST',{brandId:S.brandId,enabled:f.has('enabled'),automatic:f.has('automatic')});await refresh();render();notify('Google Drive sync preferences saved.');}
    if(form.id==='brandForm'){const stage=S.data.stages[S.stage],answers={};for(const field of stage.fields){answers[field.key]=field.type==='multi'?f.getAll(field.key):f.get(field.key);if(f.has(field.key+'Custom'))answers[field.key+'Custom']=f.get(field.key+'Custom');if(field.required && (!answers[field.key]||!answers[field.key].length))throw new Error(`Please answer: ${field.label}`);}await api(`/brands/${S.brandId}`,'PUT',{version:brand().version,answers,stage:Math.min(S.stage+1,S.data.stages.length-1)});await refresh();S.plan=null;if(S.stage<S.data.stages.length-1)S.stage++;else S.page='style';render();notify('Your answers are saved.');}
    if(form.id==='newPostForm'){const p=await api('/posts','POST',{brandId:S.brandId,...Object.fromEntries(f)});closeModal();await refresh();await openPost(p.id);}
    if(form.id==='postForm'){await savePost();notify('New version saved. Review checks reset.');}
    if(form.id==='uploadForm') {for(const file of f.getAll('files')){if(file.size>20*1024*1024)throw new Error('Each file must be under 20 MB.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('/assets','POST',{brandId:S.brandId,name:file.name,role:f.get('role'),fontFamily:f.get('fontFamily'),provenance:f.get('provenance'),rightsConfirmed:f.has('rightsConfirmed'),base64});}closeModal();await refresh();render();notify('Files saved to the private brand library.');}
    if(form.id==='scheduleForm'){
      let grantId=f.get('grantId');const p=S.draft;
      if(!grantId){if(!f.has('authorize'))throw new Error('Confirm permission for this post or select an existing grant.');const expires=new Date(`${f.get('local')}:00Z`);expires.setUTCDate(expires.getUTCDate()+14);const grant=await api('/grants','POST',{brandId:p.brandId,scope:'post',provider:f.get('provider'),platform:p.platform,placement:p.placement,account:f.get('account'),accountId:f.get('accountId'),postIds:[p.id],expiresAt:expires.toISOString()});grantId=grant.id;}
      S.draft=await api(`/posts/${p.id}/schedule`,'POST',{version:p.version,grantId,local:f.get('local'),timezone:f.get('timezone'),occurrence:f.get('occurrence')});closeModal();await refresh();render();notify('Queued locally. The engine must stay online at the due time.');
    }
    if(form.id==='receiptForm'){S.draft=await api(`/posts/${S.draft.id}/receipt`,'POST',{version:S.draft.version,url:f.get('url'),account:f.get('account'),musicVerified:f.has('musicVerified')});closeModal();await refresh();render();}
    if(form.id==='loginForm'){const session=await api('/session','POST',{token:f.get('token')});S.csrf=session.csrf;closeModal();await refresh();render();}
  } catch(error){notify(error.message,true);}finally{if(submit)submit.disabled=false;}
});
window.addEventListener('beforeunload',event=>{if(S.dirty){event.preventDefault();event.returnValue='';}});
try{const session=await api('/session','POST',{});S.csrf=session.csrf;await refresh();render();}catch(error){$('#app').innerHTML='<div class="boot">VIRAX <span>Open your private studio.</span></div>';modal('<h2>Private studio access</h2><p>Enter the access token configured by the studio owner.</p><form id="loginForm"><div class="field"><label for="accessToken">Access token</label><input id="accessToken" name="token" type="password" autocomplete="current-password" required></div><button class="primary">Open studio</button></form>');}
